-- ---------------------------------------------------------------------------
-- 6. Review: existing rows not touched by this import
--    (Should be empty on a clean database; review before re-running)
-- ---------------------------------------------------------------------------

SELECT part_code, part_name, category
FROM   parts_catalogue
WHERE  updated_at IS NULL
ORDER  BY part_code;

COMMIT;
